// HasOauthGrant applies the HasEdge predicate on the "oauth_grant" edge.
func HasOauthGrant() predicate.OauthToken {
	return predicate.OauthToken(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OauthGrantTable, OauthGrantColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOauthGrantWith applies the HasEdge predicate on the "oauth_grant" edge with a given conditions (other predicates).
func HasOauthGrantWith(preds ...predicate.OauthGrant) predicate.OauthToken {
	return predicate.OauthToken(func(s *sql.Selector) {
		step := newOauthGrantStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OauthToken) predicate.OauthToken {
	return predicate.OauthToken(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OauthToken) predicate.OauthToken {
	return predicate.OauthToken(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OauthToken) predicate.OauthToken {
	return predicate.OauthToken(sql.NotPredicates(p))
}
